function memo(fn) {
  const cache = new Map();
  return (n) => {
    if (cache.has(n)) return cache.get(n);
    const v = fn(n);
    cache.set(n, v);
    return v;
  };
}
let calls = 0;
const sq = memo((n) => { calls++; return n * n; });
sq(3); sq(3); sq(4); sq(3);
console.log(calls);

